let adminLatitude = null, adminLongitude = null, isProcessing = false;
const isGeofencingActive = window.appConfig.isGeofencingActive;

if (navigator.geolocation) {
    navigator.geolocation.watchPosition(
        position => {
            adminLatitude = position.coords.latitude;
            adminLongitude = position.coords.longitude;
            console.log("GPS Terkunci:", adminLatitude, adminLongitude);
            const locStatus = document.getElementById("location-status");
            if (locStatus) {
                locStatus.className = "mb-4 text-center text-xs py-2 px-4 rounded-xl bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 flex items-center justify-center gap-2";
                locStatus.innerHTML = '<span class="w-2 h-2 rounded-full bg-emerald-400"></span> Koordinat GPS Berhasil Dikunci';
            }
        },
        error => {
            console.warn("GPS Error:", error.message);
            const locStatus = document.getElementById("location-status");
            if (locStatus) {
                locStatus.className = "mb-4 text-center text-xs py-2 px-4 rounded-xl bg-red-500/10 text-red-400 border border-red-500/20 flex items-center justify-center gap-2";
                locStatus.innerHTML = '<span class="w-2 h-2 rounded-full bg-red-400"></span> GPS Error! Aktifkan Izin Lokasi Perangkat';
            }
        },
        { enableHighAccuracy: true, timeout: 10000 }
    );
}

document.addEventListener("DOMContentLoaded", function () {
    const html5QrCode = new Html5Qrcode("reader");
    const qrConfig = {
        fps: 35,
        qrbox: function (viewfinderWidth, viewfinderHeight) {
            const qrboxSize = Math.floor(0.9 * Math.min(viewfinderWidth, viewfinderHeight));
            return { width: qrboxSize, height: qrboxSize };
        },
        aspectRatio: 1,
        experimentalFeatures: { useBarCodeDetectorIfSupported: true },
        rememberLastUsedCamera: true,
        formatsToSupport: [Html5QrcodeSupportedFormats.QR_CODE]
    };

    const onScanSuccess = (decodedText, decodedResult) => {
        if (isProcessing) return;

        if (isGeofencingActive && (!adminLatitude || !adminLongitude)) {
            return Swal.fire({
                title: "GPS Tidak Siap",
                text: "Aplikasi tidak dapat mendeteksi lokasi Anda. Tolong izinkan GPS pada browser HP Admin terlebih dahulu!",
                icon: "warning",
                background: "#571319",
                color: "#e2e8f0",
                confirmButtonColor: "#e11d48",
                customClass: { popup: "rounded-[24px]", confirmButton: "rounded-xl font-bold px-4 py-2", cancelButton: "rounded-xl font-medium px-4 py-2" }
            });
        }

        isProcessing = true;
        const beep = document.getElementById("beep-sound");
        if (beep) beep.play().catch(err => console.log("Audio diblokir"));

        fetch(window.appConfig.attendanceRoute, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "X-CSRF-TOKEN": document.querySelector('meta[name="csrf-token"]').getAttribute("content")
            },
            body: JSON.stringify({
                qr_token: decodedText,
                latitude: adminLatitude,
                longitude: adminLongitude
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.status === "success") {
                const isHadir = data.status_absen === "HADIR";
                const statusColor = isHadir ? "#22c55e" : "#f59e0b";
                const logDiv = document.getElementById("scan-logs");
                if (logDiv) {
                    logDiv.innerHTML = `
                        <div class="flex justify-between items-center bg-[#0f172a] p-2.5 rounded-xl border border-rose-800">
                            <span class="truncate max-w-[150px] font-bold text-white">${data.user_name}</span>
                            <span style="color:${statusColor}" class="font-bold text-xs uppercase">${data.status_absen}</span>
                        </div>
                    `;
                }

                const noteHtml = data.notes ? `<div style="margin-top:6px;font-size:12px;color:#cbd5e1;">${data.notes}</div>` : '';

                Swal.fire({
                    title: data.message,
                    html: `Pengurus: <b>${data.user_name}</b><br>Status: <b style="color:${statusColor}">${data.status_absen}</b>${noteHtml}`,
                    icon: isHadir ? "success" : "warning",
                    background: "#571319",
                    color: "#e2e8f0",
                    confirmButtonColor: isHadir ? "#0ea5e9" : "#f59e0b",
                    confirmButtonText: "Lanjut Scan",
                    customClass: { popup: "rounded-[24px]", confirmButton: "rounded-xl font-bold px-4 py-2" }
                }).then(() => {
                    isProcessing = false;
                });
            } else {
                Swal.fire({
                    title: "Presensi Gagal",
                    text: data.message,
                    icon: "error",
                    background: "#571319",
                    color: "#e2e8f0",
                    confirmButtonColor: "#ef4444",
                    confirmButtonText: "Coba Lagi",
                    customClass: { popup: "rounded-[24px]", confirmButton: "rounded-xl font-bold px-4 py-2" }
                }).then(() => {
                    isProcessing = false;
                });
            }
        })
        .catch(error => {
            console.error("Error:", error);
            Swal.fire({
                title: "Terjadi Kesalahan",
                text: "Gagal memproses data ke server.",
                icon: "error",
                background: "#571319",
                color: "#e2e8f0",
                customClass: { popup: "rounded-[24px]", confirmButton: "rounded-xl font-bold px-4 py-2" }
            }).then(() => {
                isProcessing = false;
            });
        });
    };

    Html5Qrcode.getCameras().then(devices => {
        if (devices && devices.length > 0) {
            let cameraId = devices[0].id;
            for (let i = 0; i < devices.length; i++) {
                if (devices[i].label.toLowerCase().includes("back") || devices[i].label.toLowerCase().includes("rear")) {
                    cameraId = devices[i].id;
                    break;
                }
            }
            html5QrCode.start(cameraId, qrConfig, onScanSuccess).catch(err => console.error(err));
        }
    }).catch(err => {
        html5QrCode.start({ facingMode: "user" }, qrConfig, onScanSuccess).catch(e => console.error(e));
    });
});
